<label><?= e($positionText('Sphäre / Kostenstelle (KOST1)')) ?><select class="form-control" name="position_sphere[]"><option value=""><?= e($positionText('Sphäre wählen')) ?></option><?php foreach(TaxCatalog::costCenters() as $key=>$name): ?><option value="<?= $key ?>" <?= (string)$key===$p['sphere']?'selected':'' ?>><?= e($key.' '.$positionText($name)) ?></option><?php endforeach ?><?php if($p['sphere']!==''&&!isset(TaxCatalog::costCenters()[$p['sphere']])):?><option value="<?=e($p['sphere'])?>" selected><?=e($p['sphere'].' · '.$positionText('Auswahl prüfen'))?></option><?php endif?></select></label>
