<label><?= e($positionText('Steuer')) ?><select class="form-control" name="position_tax[]" data-position-tax><?php foreach(in_array($positionKind,['donation','goods'],true)?['0']:['0','7','19'] as $rate): ?><option value="<?= e($rate) ?>" <?= $p['tax_rate']===$rate?'selected':'' ?>><?= e($rate) ?> %</option><?php endforeach ?><?php if(!in_array($p['tax_rate'],in_array($positionKind,['donation','goods'],true)?['0']:['0','7','19'],true)):?><option value="<?=e($p['tax_rate'])?>" selected><?=e($p['tax_rate'].' % · '.$positionText('Auswahl prüfen'))?></option><?php endif?></select></label>
