<?php if($positionKind==='expense'&&$positionInputTaxEligibility==='no'): ?><input type="hidden" name="position_input_tax[]" value="none"><p class="muted"><?= e($positionText('Vorsteuerabzug:')) ?> <strong><?= e($positionText('Nein')) ?></strong> <?= e($positionText('– durch die Vereinseinstellung festgelegt.')) ?></p><?php else: ?><label <?= $positionKind!=='expense'?'hidden':'' ?>><?= e($positionText('Vorsteuerabzug für diese Ausgabe')) ?><select class="form-control" name="position_input_tax[]" <?= $positionKind!=='expense'?'disabled':'' ?>><?php foreach(InputTaxTreatment::OPTIONS as $value=>$label): ?><option value="<?= e($value) ?>" <?= ($p['input_tax']??$positionInputTaxDefault)===$value?'selected':'' ?>><?= e($positionText($label)) ?></option><?php endforeach ?></select><small><?= e($positionText('Die Umsatzsteuer laut Rechnung bleibt unverändert. Bei „Kein Vorsteuerabzug“ bleibt der BU-Schlüssel leer. Bei teilweise abziehbarer Vorsteuer die Position sachgerecht aufteilen und fachlich prüfen.')) ?></small></label><?php endif; ?>
<?php if($positionSimpleLayout): ?></details><?php else: ?><label><?= e($positionText('Betrag brutto (EUR)')) ?><input class="form-control" name="position_amount[]" inputmode="decimal" required placeholder="0,00" value="<?= e($p['amount']) ?>" data-position-amount></label><?php endif ?>
<button type="button" class="btn btn-outline theme-secondary text-button position-remove" data-remove-position><?= e($positionText('Position entfernen')) ?></button><?php if($positionServerControls):?><noscript><button type="submit" class="btn btn-outline theme-secondary" name="manual_move" value="remove:<?= $ordinal ?>" formnovalidate <?=count($positionForm)<=1?'disabled':''?>><?= e($positionText('Diese Position entfernen')) ?></button></noscript><?php endif?>
</fieldset><?php };
?>
